-- Grainbuds real menu (from the previous website, prices in EUR).
-- Idempotent: re-running updates names/prices on existing slugs.
-- Run after schema.sql: SQL Editor -> New query -> paste -> Run.

on conflict (slug) do update set name = excluded.name, name_de = excluded.name_de, sort_order = excluded.sort_order;

on conflict (slug) do update set
  category_id = excluded.category_id,
  name = excluded.name,
  name_de = excluded.name_de,
  description = excluded.description,
  description_de = excluded.description_de,
  price_cents = excluded.price_cents,
  image_url = coalesce(grainbuds_products.image_url, excluded.image_url),
  is_featured = excluded.is_featured,
  sort_order = excluded.sort_order;
